INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_PRISMA', 'ATTIVA_SMISTAMENTO_ARRIVO', 'Parametro che indica se un protocollo in ARRIVO deve essere smistato in automatico, invocando la chiamata smistamentoAction facendo inoltre l''eseguito, se impostato a 1 allora verrà attivata tale funzionalità altrimenti no.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_PRISMA', 'VALORIZZA_DATADOCUMENTO', 'Parametro che indica se deve essere valorizzato il parametro dataDocumento all''interno dei parametri nella segnatura di protocollazione, in alcune installazioni il parametro è obbligatorio, nel caso specifico comunque può essere evitato di essere compilato facendo impostare, lato protocollo, il parametro DATA_ARRIVO_OB_1 a N. Se impostato a 1 riporterà la data di protocollazione corrente nel formato dd/MM/yyyy.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('NODO_PAGAMENTI', 'SOGGETTO_PENDENZA', 'Parametro che determina se la posizione debitoria deve essere aperta verso l''azienda o direttamente verso il richiedente. Se non popolato prendera'' di dafault il richiedente.');